-- Sample Data for Mood-Based Recipe Recommender
-- Insert after running schema.sql

USE `mood_food_recommender`;

-- Insert Moods
INSERT INTO `moods` (`name`, `slug`, `description`, `icon`, `color`, `food_intent`) VALUES
('Happy', 'happy', 'Celebrate with bright, colorful, and uplifting foods!', '😊', '#FFB6C1', 'Celebratory, light, bright, colorful, sweet treats, fresh ingredients'),
('Stressed', 'stressed', 'Comfort foods to soothe and relax your mind.', '😰', '#FFA0B4', 'Comforting, warm, soothing, hearty, familiar flavors, stress-relieving ingredients'),
('Tired', 'tired', 'Energy-boosting meals to recharge and revitalize.', '😴', '#FF8FA3', 'High protein, energizing, nutrient-dense, quick to prepare, caffeine-rich options'),
('Bored', 'bored', 'Fun, creative dishes to spark curiosity and joy.', '🤔', '#FF92B6', 'Fusion meals, playful plating, unexpected textures and toppings'),
('Romantic', 'romantic', 'Cozy, aesthetic meals perfect for special moments.', '❤️', '#FF6D8C', 'Pastas, chocolate desserts, candlelight-ready comfort dishes'),
('Angry', 'angry', 'Crunchy, spicy dishes to release tension and fire up tastebuds.', '😡', '#FF4F6E', 'Chili noodles, crispy snacks, bold heat-forward flavors'),
('Relaxed', 'relaxed', 'Mild, warm, slow-food plates to keep you grounded.', '😌', '#FDB7D0', 'Tea blends, stews, slow-simmered soups and congee'),
('Rainy', 'rainy', 'Cozy, warm comfort bowls for grey-day cuddles.', '🌧️', '#B0E0E6', 'Pakoras, spiced teas, steamed buns, brothy noodles'),
('Sunny', 'sunny', 'Fresh, cool bites that feel like sunshine.', '☀️', '#FFD27F', 'Citrus salads, iced drinks, chilled noodles, seasonal fruits');

-- Insert Cuisines
