('Nepali', 'nepali', '🇳🇵'),
('Indian', 'indian', '🇮🇳'),
('American', 'american', '🇺🇸'),
('Chinese', 'chinese', '🇨🇳'),
('Japanese', 'japanese', '🇯🇵'),
('Italian', 'italian', '🇮🇹'),
